'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api), ['bearingDegrees']);
const { bearingDegrees } = api;

const invalidPoints = [
  null, undefined, [], 3, 'point', {},
  { x: 0 }, { y: 0 }, { x: '0', y: 0 },
  { x: 0, y: NaN }, { x: Infinity, y: 0 }, { x: 0, y: -Infinity }
];
for (const point of invalidPoints) {
  assert.throws(() => bearingDegrees(point, { x: 0, y: 0 }), TypeError);
  assert.throws(() => bearingDegrees({ x: 0, y: 0 }, point), TypeError);
}

const origin = { x: 4, y: -2 };
assert.equal(bearingDegrees(origin, { x: 5, y: -2 }), 0);
assert.equal(bearingDegrees(origin, { x: 4, y: -1 }), 90);
assert.equal(bearingDegrees(origin, { x: 3, y: -2 }), 180);
assert.equal(bearingDegrees(origin, { x: 4, y: -3 }), 270);
assert.equal(bearingDegrees({ x: 0, y: 0 }, { x: 1, y: 1 }), 45);
assert.equal(bearingDegrees({ x: 0, y: 0 }, { x: -1, y: 1 }), 135);
assert.equal(bearingDegrees({ x: 0, y: 0 }, { x: -1, y: -1 }), 225);
assert.equal(bearingDegrees({ x: 0, y: 0 }, { x: 1, y: -1 }), 315);
assert.equal(bearingDegrees({ x: 2, y: 3 }, { x: 2, y: 3 }), null);

const target = { x: 10, y: 20 };
const originCopy = { ...origin };
const targetCopy = { ...target };
const result = bearingDegrees(origin, target);
assert.ok(result >= 0 && result < 360);
assert.deepEqual(origin, originCopy);
assert.deepEqual(target, targetCopy);

